353	    public Mono<ServerResponse> sendEmailVerificationCode(ServerRequest request) {
354	        var emailMono = request.bodyToMono(EmailVerifyRequest.class)
355	                .switchIfEmpty(Mono.error(() -> new ServerWebInputException("Request body is required.")))
356	                .doOnNext(emailReq -> {
357	                    var bindingResult = ValidationUtils.validate(emailReq, validator, request.exchange());
358	                    if (bindingResult.hasErrors()) {
359	                        // only email field is validated
360	                        throw new ServerWebInputException("validation.error.email.pattern");
361	                    }
362	                })
363	                .map(EmailVerifyRequest::email)
364	                .map(String::toLowerCase);
365	        return Mono.zip(emailMono, getAuthenticatedUserName())
366	                .flatMap(tuple -> {
367	                    var email = tuple.getT1();
368	                    var username = tuple.getT2();
369	                    return Mono.just(username)
370	                            .transformDeferred(sendEmailVerificationCodeRateLimiter(username))
371	                            .flatMap(u -> emailVerificationService.sendVerificationCode(username, email))
372	                            .onErrorMap(RequestNotPermitted.class, RateLimitExceededException::new);
373	                })
374	                .then(ServerResponse.ok().build());
375	    }
