425	    private Mono<ServerResponse> uploadAvatarFor(ServerRequest request, Mono<User> userMono) {
426	        return request.body(BodyExtractors.toMultipartData())
427	                .map(AvatarUploadRequest::new)
428	                .flatMap(this::uploadAvatar)
429	                .flatMap(attachment -> userMono.flatMap(user -> {
430	                            MetadataUtil.nullSafeAnnotations(user)
431	                                    .put(
432	                                            User.AVATAR_ATTACHMENT_NAME_ANNO,
433	                                            attachment.getMetadata().getName());
434	                            return client.update(user);
435	                        })
436	                        .retryWhen(Retry.backoff(5, Duration.ofMillis(100))
437	                                .filter(OptimisticLockingFailureException.class::isInstance)))
438	                .flatMap(user -> ServerResponse.ok().bodyValue(user));
439	    }
