501	    private Mono<ServerResponse> createUser(ServerRequest request) {
502	        return request.bodyToMono(CreateUserRequest.class)
503	                .doOnNext(createUserRequest -> {
504	                    if (StringUtils.isBlank(createUserRequest.name())) {
505	                        throw new ServerWebInputException("Name is required");
506	                    }
