516	                            .fetch(SystemSetting.User.GROUP, SystemSetting.User.class)
517	                            .mapNotNull(SystemSetting.User::getDefaultRole)
518	                            .filter(StringUtils::isNotBlank)
519	                            .filter(role -> !AuthorityUtils.SUPER_ROLE_NAME.equals(role))
520	                            .switchIfEmpty(Mono.error(() -> new UnsatisfiedAttributeValueException(
521	                                    "problemDetail.user.signup.defaultRoleMissing")))
522	                            .flatMap(defaultRole -> userService.createUser(newUser, Set.of(defaultRole)));
