529	    private Mono<ServerResponse> updateUserProfile(ServerRequest request) {
530	        var username = request.pathVariable("name");
531	        return request.bodyToMono(UpdateUserProfileRequest.class)
532	                .switchIfEmpty(Mono.error(() -> new ServerWebInputException("Request body is required.")))
533	                .doOnNext(profile -> {
534	                    if (StringUtils.isBlank(profile.displayName()) || StringUtils.isBlank(profile.email())) {
535	                        throw new ServerWebInputException("Display name and email are required.");
536	                    }
537	                })
538	                .flatMap(profile -> client.get(User.class, username).flatMap(user -> {
539	                    var spec = user.getSpec();
540	                    var authorization = Objects.equals(spec.getEmail(), profile.email())
541	                            ? Mono.<Void>empty()
542	                            : requireSuperAdministrator();
543	                    return authorization.then(Mono.defer(() -> {
544	                        spec.setDisplayName(profile.displayName());
545	                        spec.setEmail(profile.email());
546	                        spec.setAvatar(profile.avatar());
547	                        spec.setPhone(profile.phone());
548	                        spec.setBio(profile.bio());
549	                        var oldAnnotations = MetadataUtil.nullSafeAnnotations(user);
550	                        var annotations = new HashMap<>(defaultIfNull(profile.annotations(), Map.<String, String>of()));
551	                        for (var key : List.of(
552	                                User.EMAIL_TO_VERIFY,
553	                                User.LAST_AVATAR_ATTACHMENT_NAME_ANNO,
554	                                User.AVATAR_ATTACHMENT_NAME_ANNO)) {
555	                            if (oldAnnotations.containsKey(key)) {
556	                                annotations.put(key, oldAnnotations.get(key));
557	                            } else {
558	                                annotations.remove(key);
559	                            }
560	                        }
561	                        user.getMetadata().setAnnotations(annotations);
562	                        return client.update(user);
563	                    }));
564	                }))
565	                .flatMap(user -> ServerResponse.ok().bodyValue(user));
566	    }
