662	    public Mono<ServerResponse> updateProfile(ServerRequest request) {
663	        return getAuthenticatedUserName()
664	                .flatMap(currentUserName -> client.get(User.class, currentUserName))
665	                .flatMap(currentUser -> request.bodyToMono(UpdateMyProfileRequest.class)
666	                        .switchIfEmpty(Mono.error(() -> new ServerWebInputException("Request body is required.")))
667	                        .doOnNext(profile -> {
668	                            if (StringUtils.isBlank(profile.displayName())) {
669	                                throw new ServerWebInputException("Display name is required.");
670	                            }
671	                        })
672	                        .filterWhen(profile -> {
673	                            var newDisplayName = profile.displayName();
674	                            var oldDisplayName = currentUser.getSpec().getDisplayName();
675	                            if (Objects.equals(oldDisplayName, newDisplayName)) {
