38	    public CategoryConsoleService(ReactiveExtensionClient client) {
39	        this.client = client;
40	    }
41	
42	    Mono<List<CategoryTreeNode>> listTree() {
43	        return listCategories().collectList().map(CategoryConsoleService::listToTree);
44	    }
