46	    Mono<List<CategoryTreeNode>> updatePosition(String name, CategoryPositionRequest request) {
47	        return Mono.defer(() -> move(name, normalize(request.parentName()), normalize(request.beforeName())))
48	                .retryWhen(Retry.backoff(1, Duration.ofMillis(100))
49	                        .filter(OptimisticLockingFailureException.class::isInstance))
50	                .onErrorMap(
51	                        Exceptions::isRetryExhausted,
52	                        error -> new ResponseStatusException(HttpStatus.CONFLICT, "problemDetail.conflict", error));
53	    }
