55	    private Mono<List<CategoryTreeNode>> move(String name, String targetParentName, String beforeName) {
56	        return listCategories()
57	                .collectList()
58	                .flatMap(categories -> applyMove(name, targetParentName, beforeName, categories));
59	    }
60	
61	    private Mono<List<CategoryTreeNode>> applyMove(
62	            String name, String targetParentName, String beforeName, List<Category> categories) {
63	        var categoryMap = categories.stream()
64	                .collect(Collectors.toMap(
65	                        category -> category.getMetadata().getName(),
66	                        Function.identity(),
67	                        (left, right) -> left,
68	                        LinkedHashMap::new));
69	        var moved = categoryMap.get(name);
70	        if (moved == null) {
71	            return Mono.error(new NotFoundException(
72	                    "problemDetail.category.notFound",
73	                    new Object[] {name},
74	                    "Category with name " + name + " not found"));
75	        }
76	
77	        if (targetParentName != null) {
78	            if (Objects.equals(targetParentName, name)) {
79	                return Mono.error(new UnsatisfiedAttributeValueException("problemDetail.hierarchy.self"));
80	            }
81	            if (!categoryMap.containsKey(targetParentName)) {
82	                return Mono.error(new UnsatisfiedAttributeValueException("problemDetail.hierarchy.parentMissing"));
83	            }
84	            if (isDescendant(targetParentName, name, categoryMap)) {
85	                return Mono.error(new UnsatisfiedAttributeValueException("problemDetail.hierarchy.descendant"));
86	            }
87	        }
88	
89	        if (beforeName != null && !categoryMap.containsKey(beforeName)) {
90	            return Mono.error(new UnsatisfiedAttributeValueException("problemDetail.hierarchy.beforeMissing"));
91	        }
92	
93	        var originalStates = categories.stream()
94	                .collect(Collectors.toMap(
95	                        category -> category.getMetadata().getName(),
96	                        category -> new HierarchyState(parentNameOf(category), priorityOf(category)),
97	                        (left, right) -> left,
98	                        LinkedHashMap::new));
99	        var parentMap = effectiveParentMap(categories);
100	        var originalParentName = parentMap.get(name);
101	
102	        var targetSiblings = siblings(categories, parentMap, targetParentName, name);
103	        int insertIndex = targetSiblings.size();
104	        if (beforeName != null) {
105	            insertIndex = indexOf(targetSiblings, beforeName);
106	            if (insertIndex < 0) {
107	                return Mono.error(new UnsatisfiedAttributeValueException("problemDetail.hierarchy.notSibling"));
108	            }
109	        }
110	        targetSiblings.add(insertIndex, moved);
111	        assignPriorities(targetSiblings, targetParentName);
112	
113	        if (!Objects.equals(originalParentName, targetParentName)) {
114	            assignPriorities(siblings(categories, parentMap, originalParentName, name), originalParentName);
115	        }
116	
117	        var changedCategories = categories.stream()
118	                .filter(category -> hasHierarchyChanged(
119	                        category, originalStates.get(category.getMetadata().getName())))
120	                .toList();
121	
122	        return Flux.fromIterable(changedCategories)
123	                .concatMap(client::update)
124	                .then(Mono.fromSupplier(() -> listToTree(categories)));
125	    }
