131	    static List<CategoryTreeNode> listToTree(Collection<Category> categories) {
132	        Map<String, CategoryTreeNode> categoryMap = categories.stream()
133	                .map(category -> new CategoryTreeNode(category, new ArrayList<>()))
134	                .collect(Collectors.toMap(
135	                        node -> node.getCategory().getMetadata().getName(),
136	                        Function.identity(),
137	                        (left, right) -> left,
138	                        LinkedHashMap::new));
139	        Map<String, String> parentMap = effectiveParentMap(categories);
140	
141	        categoryMap.forEach((name, node) -> {
142	            var parentName = parentMap.get(name);
143	            if (parentName != null) {
144	                categoryMap.get(parentName).getChildren().add(node);
145	            }
146	        });
147	
148	        var roots = categoryMap.values().stream()
149	                .filter(node -> {
150	                    var name = node.getCategory().getMetadata().getName();
151	                    return !parentMap.containsKey(name);
152	                })
153	                .collect(Collectors.toCollection(ArrayList::new));
154	        sortTree(roots);
155	        return roots;
156	    }
157	
158	    private static Map<String, String> effectiveParentMap(Collection<Category> categories) {
159	        var names = categories.stream()
160	                .map(category -> category.getMetadata().getName())
161	                .collect(Collectors.toSet());
162	        Map<String, String> parentMap = new LinkedHashMap<>();
163	        categories.forEach(category -> {
164	            var name = category.getMetadata().getName();
165	            var parentName = parentNameOf(category);
166	            if (parentName != null && !Objects.equals(parentName, name) && names.contains(parentName)) {
167	                parentMap.put(name, parentName);
168	            }
169	        });
170	        parentMap.keySet().removeAll(cyclicNames(parentMap));
171	        return parentMap;
172	    }
173	
174	    private static Set<String> cyclicNames(Map<String, String> parentMap) {
175	        Set<String> cyclicNames = new HashSet<>();
176	        for (String name : parentMap.keySet()) {
177	            var path = new ArrayList<String>();
178	            var visiting = new HashSet<String>();
179	            var current = name;
180	            while (current != null && parentMap.containsKey(current)) {
181	                if (!visiting.add(current)) {
182	                    cyclicNames.addAll(path.subList(path.indexOf(current), path.size()));
183	                    break;
184	                }
185	                path.add(current);
186	                current = parentMap.get(current);
187	            }
188	        }
189	        return cyclicNames;
190	    }
