192	    private static void sortTree(List<CategoryTreeNode> nodes) {
193	        nodes.sort(Comparator.comparing(CategoryTreeNode::getCategory, defaultCategoryComparator()));
194	        nodes.forEach(node -> sortTree(node.getChildren()));
195	    }
