197	    private static Comparator<Category> defaultCategoryComparator() {
198	        return Comparator.comparing(CategoryConsoleService::priorityOf)
199	                .thenComparing(
200	                        CategoryConsoleService::creationTimestampOf, Comparator.nullsFirst(Comparator.naturalOrder()))
201	                .thenComparing(category -> category.getMetadata().getName());
202	    }
