222	    private static boolean isDescendant(String candidateName, String ancestorName, Map<String, Category> categoryMap) {
223	        var current = candidateName;
224	        var visited = new HashSet<String>();
225	        while (current != null) {
226	            if (Objects.equals(current, ancestorName)) {
227	                return true;
228	            }
229	            if (!visited.add(current)) {
230	                throw new UnsatisfiedAttributeValueException("problemDetail.hierarchy.cycle");
231	            }
232	            current = Optional.ofNullable(categoryMap.get(current))
233	                    .map(CategoryConsoleService::parentNameOf)
234	                    .orElse(null);
235	        }
236	        return false;
237	    }
238	
239	    private static List<Category> siblings(
240	            List<Category> categories, Map<String, String> parentMap, String parentName, String excludingName) {
241	        return categories.stream()
242	                .filter(category -> !Objects.equals(category.getMetadata().getName(), excludingName))
243	                .filter(category ->
244	                        Objects.equals(parentMap.get(category.getMetadata().getName()), parentName))
245	                .sorted(defaultCategoryComparator())
246	                .collect(Collectors.toCollection(ArrayList::new));
247	    }
248	
249	    private static int indexOf(List<Category> categories, String name) {
250	        for (int i = 0; i < categories.size(); i++) {
251	            if (Objects.equals(categories.get(i).getMetadata().getName(), name)) {
252	                return i;
253	            }
254	        }
255	        return -1;
256	    }
257	
258	    private static void assignPriorities(List<Category> siblings, String parentName) {
259	        for (int i = 0; i < siblings.size(); i++) {
260	            var category = siblings.get(i);
261	            if (category.getSpec() == null) {
262	                category.setSpec(new Category.CategorySpec());
263	            }
264	            category.getSpec().setParent(parentName);
265	            category.getSpec().setPriority(i);
266	        }
267	    }
268	
269	    private static boolean hasHierarchyChanged(Category category, HierarchyState original) {
270	        if (original == null) {
271	            return false;
272	        }
273	        return !Objects.equals(parentNameOf(category), original.parentName())
274	                || priorityOf(category) != original.priority();
275	    }
276	
277	    private static String normalize(String value) {
278	        return org.springframework.util.StringUtils.hasText(value) ? value : null;
279	    }
280	
281	    private record HierarchyState(String parentName, int priority) {}
282	}
