470	    private Mono<ServerResponse> updatePluginConfig(ServerRequest request) {
471	        final var pluginName = request.pathVariable("name");
472	        return client.fetch(Plugin.class, pluginName)
473	                .doOnNext(plugin -> {
474	                    String configMapName = plugin.getSpec().getConfigMapName();
475	                    if (!StringUtils.hasText(configMapName)) {
