481	                    final String configMapName = plugin.getSpec().getConfigMapName();
482	                    return request.bodyToMono(ConfigMap.class)
483	                            .doOnNext(configMapToUpdate -> {
484	                                var configMapNameToUpdate =
485	                                        configMapToUpdate.getMetadata().getName();
486	                                if (!configMapName.equals(configMapNameToUpdate)) {
487	                                    throw new ServerWebInputException(
488	                                            "The name from the request body does not match the plugin "
489	                                                    + "configMapName name.");
490	                                }
491	                            })
492	                            .flatMap(configMapToUpdate -> client.fetch(ConfigMap.class, configMapName)
493	                                    .map(persisted -> {
494	                                        configMapToUpdate
495	                                                .getMetadata()
496	                                                .setVersion(
497	                                                        persisted.getMetadata().getVersion());
498	                                        return configMapToUpdate;
499	                                    })
500	                                    .switchIfEmpty(client.create(configMapToUpdate)))
501	                            .flatMap(client::update)
502	                            .retryWhen(Retry.backoff(5, Duration.ofMillis(300))
503	                                    .filter(OptimisticLockingFailureException.class::isInstance));
504	                })
505	                .flatMap(configMap -> ServerResponse.ok().bodyValue(configMap));
506	    }
