642	    /** Multipart payload for installing a plugin. */
643	    @Schema(name = "PluginInstallRequest", types = "object")
644	    public static class InstallRequest {
645	
646	        private final MultiValueMap<String, Part> multipartData;
647	
648	        public InstallRequest(MultiValueMap<String, Part> multipartData) {
649	            this.multipartData = multipartData;
650	        }
651	
652	        /** Plugin JAR file. */
653	        @Schema(requiredMode = NOT_REQUIRED)
654	        public FilePart getFile() {
655	            var part = multipartData.getFirst("file");
656	            if (part == null) {
657	                throw new ServerWebInputException("problemDetail.upload.fileRequired");
658	            }
659	            if (!(part instanceof FilePart file)) {
660	                throw new ServerWebInputException("problemDetail.upload.fileRequired");
661	            }
662	            if (!Paths.get(file.filename()).toString().endsWith(".jar")) {
663	                throw new UnsatisfiedAttributeValueException("problemDetail.plugin.archiveType");
664	            }
665	            return file;
666	        }
667	
668	        /** Plugin preset name. Halo finds the plugin from plugin presets. */
669	        @Schema(requiredMode = NOT_REQUIRED)
670	        public Mono<String> getPresetName() {
671	            var part = multipartData.getFirst("presetName");
672	            if (part == null) {
673	                return Mono.error(new ServerWebInputException("Form field presetName is required."));
674	            }
675	            if (!(part instanceof FormFieldPart presetName)) {
676	                return Mono.error(new ServerWebInputException("Invalid format of presetName field, string required"));
677	            }
678	            if (!StringUtils.hasText(presetName.value())) {
679	                return Mono.error(new ServerWebInputException("presetName must not be blank"));
680	            }
681	            return Mono.just(presetName.value());
682	        }
683	
684	        /** Install source. Defaults to file. */
685	        @Schema(requiredMode = NOT_REQUIRED)
686	        public Mono<InstallSource> getSource() {
687	            var part = multipartData.getFirst("source");
688	            if (part == null) {
689	                return Mono.just(InstallSource.FILE);
690	            }
691	            if (!(part instanceof FormFieldPart sourcePart)) {
692	                return Mono.error(new ServerWebInputException("Invalid format of source field, string required."));
693	            }
694	            var installSource = InstallSource.valueOf(sourcePart.value().toUpperCase());
695	            return Mono.just(installSource);
696	        }
697	    }
698	
699	    public enum InstallSource {
700	        FILE,
701	        PRESET,
702	        URL
703	    }
704	
705	    Mono<Void> deleteFileIfExists(Path path) {
706	        return deleteFileSilently(path, this.scheduler).then();
707	    }
708	
709	    private Mono<Path> writeToTempFile(Publisher<DataBuffer> content) {
710	        return Mono.fromCallable(() -> Files.createTempFile("halo-plugin-", ".jar"))
711	                .flatMap(path -> write(content, path).thenReturn(path))
712	                .subscribeOn(this.scheduler);
713	    }
