65	export async function setupUiPluginRuntime({
66	  app,
67	  router,
68	  platform,
69	  setupComponents,
70	  registeredFormKitInputs,
71	  runtime: runtimeOverrides,
72	}: {
73	  app: App;
74	  router: Router;
75	  platform: Platform;
76	  setupComponents: (options?: SetupComponentsOptions) => void;
77	  registeredFormKitInputs: FormKitLibrary;
78	  runtime?: Partial<UiPluginRuntimeDependencies>;
79	}) {
80	  const runtime = createRuntimeDependencies(runtimeOverrides);
81	  const pluginModuleStore = usePluginModuleStore();
82	  const registrationStore = stores.uiPlugins() as unknown as UiPluginsHostStore;
83	  pluginModuleStore.clearDiagnostics();
84	
85	  let descriptor: UiPluginProviderDescriptor;
86	  try {
87	    descriptor = await runtime.fetchProviders();
88	  } catch (error) {
89	    setupComponents();
90	    notifyPluginLoadError(error);
91	    return [];
92	  }
93	
94	  const providers = descriptor.providers;
95	  const registrationsByName = new Map(
96	    providers.map((provider) => [provider.name, provider])
97	  );
98	  const invalidProviders = providers.filter(
99	    (provider) => provider.kind === "invalid"
100	  );
101	  const legacyProviders = providers.filter(
102	    (provider) => provider.kind === "legacy"
103	  );
104	  const esmProviders = providers.filter((provider) => provider.kind === "esm");
105	  const styledProviders = providers.filter(
106	    (
107	      provider
108	    ): provider is UiPluginProvider & {
109	      style: string;
110	    } => provider.kind !== "invalid" && Boolean(provider.style)
111	  );
112	  const loadedStyles = new Map<string, unknown>();
113	
114	  registrationStore._seed(
115	    providers.map((provider) => ({
116	      name: provider.name,
117	      type: provider.type,
118	      version: provider.version,
119	      status: provider.kind === "invalid" ? "failed" : "pending",
120	    }))
121	  );
122	
123	  const report = (
124	    registration: UiProviderRegistration,
125	    stage: UiPluginFailureStage,
126	    error: unknown,
127	    details: Pick<UiPluginDiagnostic, "incompleteRollback"> = {}
128	  ) => {
129	    if (stage === "entry" || stage === "export" || stage === "registration") {
130	      const loadedStyle = loadedStyles.get(registration.name);
131	      if (loadedStyle !== undefined) {
132	        runtime.unloadStyle(loadedStyle);
133	        loadedStyles.delete(registration.name);
134	      }
135	    }
136	    const diagnostic: UiPluginDiagnostic = {
137	      name: registration.name,
138	      type: registration.type,
139	      stage,
140	      message: errorMessage(error),
141	      ...details,
142	    };
143	    registrationStore._setStatus(registration.name, "failed");
144	    pluginModuleStore.recordDiagnostic(diagnostic);
145	    console.error("[Halo UI provider]", diagnostic, error);
146	  };
147	
148	  for (const invalid of invalidProviders) {
149	    report(
150	      invalid,
151	      "discovery",
152	      invalid.reason || `Provider "${invalid.name}" is invalid.`
153	    );
154	  }
155	
156	  const styleInsertionPoint = document.head.firstChild;
157	  const styleLoads = styledProviders.map((provider) =>
158	    runtime.loadStyle(provider.style, styleInsertionPoint)
159	  );
160	  const legacyScriptLoad =
161	    legacyProviders.length > 0
162	      ? descriptor.legacyScript
163	        ? runtime.loadScript(descriptor.legacyScript)
164	        : Promise.reject(
165	            new Error("The UI provider descriptor has no legacy script.")
166	          )
167	      : Promise.resolve();
168	  const esmImports = esmProviders.map((provider) =>
169	    provider.entry
170	      ? runtime.importModule(provider.entry)
171	      : Promise.reject(
172	          new Error(`ESM provider "${provider.name}" has no entry.`)
173	        )
174	  );
175	
176	  const [styleResults, legacyScriptResult, esmImportResults] =
177	    await Promise.all([
178	      Promise.allSettled(styleLoads),
179	      settled(legacyScriptLoad),
180	      Promise.allSettled(esmImports),
181	    ]);
182	
183	  const failedNames = new Set(
184	    invalidProviders.map((provider) => provider.name)
185	  );
186	  const styleFailed = styleResults.some(
187	    (result) => result.status === "rejected"
188	  );
189	  for (const [index, result] of styleResults.entries()) {
190	    if (result.status === "fulfilled") {
191	      loadedStyles.set(styledProviders[index].name, result.value);
192	      continue;
193	    }
194	    const provider = styledProviders[index];
195	    failedNames.add(provider.name);
196	    report(provider, "style", result.reason);
197	  }
198	
199	  if (legacyScriptResult.status === "rejected") {
200	    for (const provider of legacyProviders) {
201	      failedNames.add(provider.name);
202	      report(provider, "entry", legacyScriptResult.reason);
203	    }
204	  }
205	
206	  const loadedByName = new Map<string, LoadedPluginModule>();
207	  const legacyProvidersWithoutModule = new Set<string>();
208	  if (legacyScriptResult.status === "fulfilled") {
209	    for (const provider of legacyProviders) {
210	      const module = window[provider.name] as unknown;
211	      if (module === undefined || module === null) {
212	        legacyProvidersWithoutModule.add(provider.name);
213	        continue;
214	      }
215	      if (!isPluginModule(module)) {
216	        failedNames.add(provider.name);
217	        report(
218	          provider,
219	          "export",
220	          new Error(
221	            `Legacy provider "${provider.name}" did not expose a PluginModule.`
222	          )
223	        );
224	        continue;
225	      }
226	      loadedByName.set(provider.name, {
227	        name: provider.name,
228	        type: provider.type,
229	        module,
230	      });
231	    }
232	  }
233	
234	  for (const [index, result] of esmImportResults.entries()) {
235	    const provider = esmProviders[index];
236	    if (result.status === "rejected") {
237	      failedNames.add(provider.name);
238	      report(provider, "entry", result.reason);
