367	function registerPluginModule({
368	  app,
369	  router,
370	  platform,
371	  registration,
372	  module,
373	  routeOwners,
374	  componentOwners,
375	  report,
376	}: {
377	  app: App;
378	  router: Router;
379	  platform: Platform;
380	  registration: UiProviderRegistration;
381	  module: PluginModule;
382	  routeOwners: Map<string | symbol, UiProviderRegistration>;
383	  componentOwners: WeakMap<object, UiProviderRegistration>;
384	  report: (
385	    registration: UiProviderRegistration,
386	    stage: UiPluginFailureStage,
387	    error: unknown
388	  ) => void;
389	}): RegistrationFailure | undefined {
390	  const rollbackHandles: RollbackHandle[] = [];
391	  const incompleteRollback: string[] = [];
392	  try {
393	    preparePluginModule(module, registration, report);
394	    commitJsModule({
395	      app,
396	      router,
397	      platform,
398	      name: registration.name,
399	      module,
400	      core: false,
401	      rollbackHandles,
402	      registration,
403	      routeOwners,
404	      componentOwners,
