423	function commitJsModule({
424	  app,
425	  router,
426	  platform,
427	  name,
428	  module,
429	  core,
430	  rollbackHandles,
431	  registration,
432	  routeOwners,
433	  componentOwners,
434	}: {
435	  app: App;
436	  router: Router;
437	  platform: Platform;
438	  name: string;
439	  module: PluginModule;
440	  core: boolean;
441	  rollbackHandles: RollbackHandle[];
442	  registration?: UiProviderRegistration;
443	  routeOwners?: Map<string | symbol, UiProviderRegistration>;
444	  componentOwners?: WeakMap<object, UiProviderRegistration>;
445	}) {
446	  const pluginModuleStore = usePluginModuleStore();
447	  const routes = platform === "console" ? module.routes : module.ucRoutes;
448	  assignInternalRouteParentNames(routes);
449	  const previousModule = pluginModuleStore.pluginModuleMap[name];
450	  pluginModuleStore.registerPluginModule(name, module);
451	  rollbackHandles.push({
452	    label: "plugin module store",
453	    rollback: () => {
454	      if (previousModule) {
455	        pluginModuleStore.registerPluginModule(name, previousModule);
456	      } else {
457	        pluginModuleStore.unregisterPluginModule(name);
458	      }
459	    },
460	  });
