462	  if (module.components) {
463	    for (const [componentName, component] of Object.entries(
464	      module.components
465	    )) {
466	      const components = app._context.components;
467	      const hadPrevious = Object.prototype.hasOwnProperty.call(
468	        components,
469	        componentName
470	      );
471	      const previousComponent = components[componentName];
472	      app.component(componentName, component);
473	      if (registration && isWeakMapKey(component)) {
474	        componentOwners?.set(component, registration);
475	      }
476	      rollbackHandles.push({
477	        label: `component ${componentName}`,
478	        rollback: () => {
479	          if (hadPrevious && previousComponent) {
480	            components[componentName] = previousComponent;
481	          } else {
482	            delete components[componentName];
483	          }
484	          if (isWeakMapKey(component)) {
485	            componentOwners?.delete(component);
486	          }
487	        },
488	      });
489	    }
490	  }
491	
492	  if (!routes) {
493	    return;
494	  }
495	  for (const route of routes) {
496	    if ("parentName" in route) {
