499	        route,
500	        rollbackHandles,
501	        registration,
502	        routeOwners,
503	        componentOwners,
504	      });
505	    } else {
506	      const replacedRoute = findReplacedRoute(router, route, routeOwners);
507	      const removeRoute = router.addRoute(route);
508	      if (replacedRoute) {
509	        unregisterRouteOwners(
510	          replacedRoute.route,
511	          routeOwners,
512	          componentOwners
513	        );
514	      }
515	      if (registration) {
516	        registerRouteOwners(route, registration, routeOwners, componentOwners);
517	      }
518	      rollbackHandles.push({
519	        label: `route ${String(route.name || route.path)}`,
520	        rollback: () => {
521	          removeRoute();
522	          unregisterRouteOwners(route, routeOwners, componentOwners);
523	          restoreReplacedRoute(
524	            router,
525	            replacedRoute,
526	            routeOwners,
527	            componentOwners
528	          );
529	        },
530	      });
531	    }
532	  }
