534	  function appendChildRoute({
535	    router,
536	    route,
537	    rollbackHandles,
538	    registration,
539	    routeOwners,
540	    componentOwners,
541	  }: {
542	    router: Router;
543	    route: RouteRecordAppend;
544	    rollbackHandles: RollbackHandle[];
545	    registration?: UiProviderRegistration;
546	    routeOwners?: Map<string | symbol, UiProviderRegistration>;
547	    componentOwners?: WeakMap<object, UiProviderRegistration>;
548	  }) {
549	    const parentRoute = router
550	      .getRoutes()
551	      .find((item) => item.name === route.parentName);
552	    if (!parentRoute) {
553	      return;
554	    }
555	    const previousChildren = [...parentRoute.children];
556	    rollbackHandles.push({
557	      label: `child route ${String(route.route.name || route.route.path)}`,
558	      rollback: () => {
559	        router.removeRoute(route.parentName);
560	        parentRoute.children = previousChildren;
561	        router.addRoute(parentRoute as unknown as RouteRecordRaw);
562	        unregisterRouteOwners(route.route, routeOwners, componentOwners);
563	      },
564	    });
565	    router.removeRoute(route.parentName);
566	    parentRoute.children = [...parentRoute.children, route.route];
567	    router.addRoute(parentRoute as unknown as RouteRecordRaw);
568	    if (registration) {
569	      registerRouteOwners(
570	        route.route,
571	        registration,
572	        routeOwners,
573	        componentOwners
574	      );
575	    }
576	  }
577	
578	  if (core) {
