598	function findReplacedRoute(
599	  router: Router,
600	  route: RouteRecordRaw,
601	  routeOwners?: Map<string | symbol, UiProviderRegistration>
602	): ReplacedRoute | undefined {
603	  if (!route.name) {
604	    return undefined;
605	  }
606	  const currentRoutes = router.getRoutes();
607	  const existing = currentRoutes.find((item) => item.name === route.name);
608	  if (!existing || existing.name === undefined) {
609	    return undefined;
610	  }
611	  const parent = findRouteParent(currentRoutes, existing.name);
612	  return {
613	    route: existing as unknown as RouteRecordRaw,
614	    parentName: parent?.name,
615	    nestedUnderAnonymousParent: Boolean(parent && !parent.name),
616	    owner: routeOwners?.get(route.name),
617	  };
618	}
