629	function restoreReplacedRoute(
630	  router: Router,
631	  replacedRoute: ReplacedRoute | undefined,
632	  routeOwners?: Map<string | symbol, UiProviderRegistration>,
633	  componentOwners?: WeakMap<object, UiProviderRegistration>
634	) {
635	  if (!replacedRoute) {
636	    return;
637	  }
638	  if (replacedRoute.nestedUnderAnonymousParent) {
639	    throw new Error(
640	      "Cannot restore a replaced route under an anonymous parent registered outside Halo's managed route setup."
641	    );
642	  }
643	  if (replacedRoute.parentName) {
644	    router.addRoute(replacedRoute.parentName, replacedRoute.route);
645	  } else {
646	    router.addRoute(replacedRoute.route);
647	  }
648	  if (replacedRoute.owner) {
649	    registerRouteOwners(
650	      replacedRoute.route,
651	      replacedRoute.owner,
652	      routeOwners,
653	      componentOwners
654	    );
655	  }
