755	function wrapChunkLoader<T extends ComponentLoader>(
756	  loader: T,
757	  registration: UiProviderRegistration,
758	  report: (
759	    registration: UiProviderRegistration,
760	    stage: UiPluginFailureStage,
761	    error: unknown
762	  ) => void
763	) {
