765	    try {
766	      const result = loader(...args);
767	      if (isPromiseLike(result)) {
768	        return result.catch((error: unknown) => {
769	          report(registration, "chunk", error);
770	          throw error;
771	        });
772	      }
773	      return result;
774	    } catch (error) {
775	      report(registration, "chunk", error);
776	      throw error;
777	    }
778	  }) as T;
