781	function installProviderErrorHooks({
782	  app,
783	  router,
784	  registrationsByName,
785	  routeOwners,
786	  componentOwners,
787	  report,
788	}: {
789	  app: App;
790	  router: Router;
791	  registrationsByName: Map<string, UiProviderRegistration>;
792	  routeOwners: Map<string | symbol, UiProviderRegistration>;
793	  componentOwners: WeakMap<object, UiProviderRegistration>;
794	  report: (
795	    registration: UiProviderRegistration,
796	    stage: UiPluginFailureStage,
797	    error: unknown
798	  ) => void;
799	}) {
800	  router.onError((error, to) => {
801	    const owner = [...to.matched]
802	      .reverse()
803	      .map((route) => route.name && routeOwners.get(route.name))
804	      .find(Boolean);
805	    if (owner) {
806	      report(owner, "chunk", error);
807	    }
808	  });
809	
810	  const previousErrorHandler = app.config.errorHandler;
811	  app.config.errorHandler = (error, instance, info) => {
812	    const isAsyncComponentError =
813	      typeof info === "string" && info.includes("async component");
814	    const component = instance?.$?.type;
815	    let handled = false;
816	    if (isAsyncComponentError) {
817	      const owner = findComponentOwner(instance?.$, componentOwners);
818	      const fallbackOwner =
819	        owner ||
820	        findMatchedRouteOwner(
821	          router.currentRoute?.value?.matched,
822	          routeOwners
823	        ) ||
824	        [...registrationsByName.values()].find(
825	          (registration) => registration.name === componentName(component)
826	        );
827	      if (fallbackOwner) {
828	        report(fallbackOwner, "chunk", error);
829	        handled = true;
830	      }
831	    }
832	    if (previousErrorHandler) {
833	      previousErrorHandler(error, instance, info);
834	    } else if (!handled) {
835	      console.error("[Vue]", info, error);
836	    }
837	  };
838	}
