138	    @Override
139	    public Result reconcile(Request request) {
140	        return client.fetch(Plugin.class, request.name())
141	                .map(plugin -> {
142	                    if (ExtensionUtil.isDeleted(plugin)) {
143	                        if (!checkDependents(plugin)) {
144	                            client.update(plugin);
145	                            // Check dependents every 10 seconds
146	                            return Result.requeue(Duration.ofSeconds(10));
147	                        }
148	                        // CleanUp resources and remove finalizer.
149	                        if (removeFinalizers(plugin.getMetadata(), Set.of(FINALIZER_NAME))) {
150	                            cleanupResources(plugin);
151	                            syncPluginState(plugin);
152	                            client.update(plugin);
153	                        }
154	                        return Result.doNotRetry();
155	                    }
156	                    addFinalizers(plugin.getMetadata(), Set.of(FINALIZER_NAME));
157	                    removeUnusedAnnotations(plugin);
158	
159	                    var status = plugin.getStatus();
160	                    if (status == null) {
161	                        status = new Plugin.PluginStatus();
162	                        plugin.setStatus(status);
163	                    }
164	                    if (status.getPhase() == null) {
165	                        // reset phase to pending
166	                        status.setPhase(Plugin.Phase.PENDING);
167	                    }
168	                    // init condition list if not exists
169	                    if (status.getConditions() == null) {
170	                        status.setConditions(new ConditionList());
171	                    }
172	
173	                    var steps = new LinkedList<Supplier<Result>>();
174	                    steps.add(() -> resolveLoadLocation(plugin));
175	                    steps.add(() -> loadOrReload(plugin));
176	                    steps.add(() -> createOrUpdateSetting(plugin));
177	                    steps.add(() -> createOrUpdateReverseProxy(plugin));
178	                    steps.add(() -> resolveStaticResources(plugin));
179	                    if (requestToEnable(plugin)) {
180	                        steps.add(() -> enablePlugin(plugin));
181	                    } else {
182	                        steps.add(() -> disablePlugin(plugin));
183	                    }
184	
185	                    Result result = null;
186	                    try {
187	                        for (var step : steps) {
188	                            result = step.get();
189	                            if (result != null) {
190	                                break;
191	                            }
192	                        }
193	                        return result;
194	                    } catch (Throwable e) {
195	                        status.getConditions()
196	                                .addAndEvictFIFO(Condition.builder()
197	                                        .type(ConditionType.READY)
198	                                        .status(ConditionStatus.FALSE)
199	                                        .reason(ConditionReason.SYSTEM_ERROR)
200	                                        .message(e.getMessage())
201	                                        .lastTransitionTime(clock.instant())
202	                                        .build());
203	                        status.setPhase(Plugin.Phase.UNKNOWN);
204	                        throw e;
205	                    } finally {
206	                        var pw = pluginManager.getPlugin(plugin.getMetadata().getName());
207	                        if (pw != null) {
208	                            status.setLastProbeState(pw.getPluginState());
209	                        }
210	                        client.update(plugin);
211	                    }
212	                })
213	                .orElseGet(Result::doNotRetry);
214	    }
