216	    private void removeUnusedAnnotations(Plugin plugin) {
217	        var annotations = plugin.getMetadata().getAnnotations();
218	        if (annotations != null) {
219	            UNUSED_ANNOTATIONS.forEach(annotations::remove);
220	        }
221	    }
