223	    private boolean checkDependents(Plugin plugin) {
224	        var pluginId = plugin.getMetadata().getName();
225	        var dependents = pluginManager.getDependents(pluginId);
226	        if (CollectionUtils.isEmpty(dependents)) {
227	            return true;
228	        }
229	        var status = plugin.statusNonNull();
230	        var condition = Condition.builder()
231	                .type(ConditionType.PROGRESSING)
232	                .status(ConditionStatus.UNKNOWN)
233	                .reason(ConditionReason.WAIT_FOR_DEPENDENTS_DELETED)
234	                .message("The plugin has dependents %s, please delete them first."
235	                        .formatted(dependents.stream()
236	                                .map(PluginWrapper::getPluginId)
237	                                .toList()))
238	                .lastTransitionTime(clock.instant())
239	                .build();
240	        var conditions = nullSafeConditions(status);
241	        removeConditionBy(conditions, ConditionType.INITIALIZED);
242	        removeConditionBy(conditions, ConditionType.READY);
243	        conditions.addAndEvictFIFO(condition);
244	        status.setPhase(Plugin.Phase.UNKNOWN);
245	        return false;
246	    }
