278	    private void cleanupResources(Plugin plugin) {
279	        var pluginName = plugin.getMetadata().getName();
280	        var reverseProxyName = buildReverseProxyName(pluginName);
281	        log.info("Deleting reverse proxy {} for plugin {}", reverseProxyName, pluginName);
282	        client.fetch(ReverseProxy.class, reverseProxyName).ifPresent(reverseProxy -> {
283	            client.delete(reverseProxy);
284	            throw new RequeueException(Result.requeue(null), String.format("""
285	                        Waiting for reverse proxy %s to be deleted.""", reverseProxyName));
286	        });
287	        var settingName = plugin.getSpec().getSettingName();
288	        if (StringUtils.isNotBlank(settingName)) {
289	            log.info("Deleting settings {} for plugin {}", settingName, pluginName);
290	            client.fetch(Setting.class, settingName).ifPresent(setting -> {
291	                client.delete(setting);
292	                throw new RequeueException(Result.requeue(null), String.format("""
293	                        Waiting for setting %s to be deleted.""", settingName));
294	            });
295	        }
296	        if (pluginManager.getPlugin(pluginName) != null) {
297	            log.info("Deleting plugin {} in plugin manager.", pluginName);
298	            var deleted = pluginManager.deletePlugin(pluginName);
299	            if (!deleted) {
300	                throw new RequeueException(
301	                        Result.requeue(Duration.ofSeconds(10)),
302	                        "Failed to delete plugin " + pluginName + " in plugin manager");
303	            }
304	        }
305	        // Clean up orphaned JARs (historical leftovers from failed upgrades/uninstalls)
306	        cleanUpOrphanedJars(pluginName);
307	    }
308	
309	    private void cleanUpOrphanedJars(String pluginName) {
310	        var prefix = pluginName + "-";
311	        for (var pluginRoot : pluginManager.getPluginsRoots()) {
312	            if (!Files.exists(pluginRoot)) {
313	                continue;
314	            }
315	            try (var files = Files.list(pluginRoot)) {
316	                files.filter(f -> {
317	                            var fn = f.getFileName().toString();
318	                            return fn.startsWith(prefix) && fn.endsWith(".jar");
319	                        })
320	                        .forEach(jar -> {
321	                            var name = readPluginNameFromJar(jar);
322	                            if (pluginName.equals(name)) {
323	                                try {
324	                                    log.info("Deleting orphaned plugin JAR {}", jar);
325	                                    Files.deleteIfExists(jar);
326	                                } catch (IOException e) {
327	                                    throw new RequeueException(
328	                                            Result.requeue(Duration.ofSeconds(10)),
329	                                            "Failed to delete orphaned JAR " + jar + " for plugin " + pluginName);
330	                                }
331	                            }
332	                        });
333	            } catch (IOException e) {
334	                log.warn("Failed to list plugins directory {} for cleanup", pluginRoot, e);
335	            }
336	        }
337	    }
