339	    private String readPluginNameFromJar(Path jarPath) {
340	        try {
341	            // YamlPluginFinder properly closes the zip FileSystem opened for the JAR.
342	            return new YamlPluginFinder().find(jarPath).getMetadata().getName();
343	        } catch (Exception e) {
344	            log.warn("Failed to read manifest from {}", jarPath, e);
345	            return null;
346	        }
347	    }
