349	    private Result enablePlugin(Plugin plugin) {
350	        // start the plugin
351	        var pluginName = plugin.getMetadata().getName();
352	        var status = plugin.getStatus();
353	        var conditions = status.getConditions();
354	        log.info("Starting plugin {}", pluginName);
355	
356	        // check if the parent plugin is started
357	        var unstartedDependencies = pluginService.getRequiredDependencies(
358	                plugin, pw -> pw == null || !PluginState.STARTED.equals(pw.getPluginState()));
359	        if (!CollectionUtils.isEmpty(unstartedDependencies)) {
360	            removeConditionBy(conditions, ConditionType.READY);
361	            conditions.addAndEvictFIFO(Condition.builder()
362	                    .type(ConditionType.PROGRESSING)
363	                    .status(ConditionStatus.UNKNOWN)
364	                    .reason(ConditionReason.WAIT_FOR_DEPENDENCIES_STARTED)
365	                    .message("Wait for parent plugins " + unstartedDependencies + " to be started")
366	                    .lastTransitionTime(clock.instant())
367	                    .build());
368	            status.setPhase(Plugin.Phase.UNKNOWN);
369	            return Result.requeue(Duration.ofSeconds(5));
370	        }
371	
372	        var current = pluginManager.getPlugin(pluginName);
373	        if (current == null) {
374	            conditions.addAndEvictFIFO(Condition.builder()
375	                    .type(ConditionType.READY)
376	                    .status(ConditionStatus.FALSE)
377	                    .reason(ConditionReason.START_ERROR)
378	                    .message("Plugin " + pluginName + " is not loaded.")
379	                    .lastTransitionTime(clock.instant())
380	                    .build());
381	            status.setPhase(Plugin.Phase.FAILED);
382	            removeStartTaskIfPresent(pluginName);
383	            return Result.doNotRetry();
384	        }
385	        var pluginState = current.getPluginState();
386	        if (pluginState.isStarted()) {
387	            removeConditionBy(conditions, ConditionType.PROGRESSING);
388	            status.setLastStartTime(clock.instant());
389	            conditions.addAndEvictFIFO(Condition.builder()
390	                    .type(ConditionType.READY)
391	                    .status(ConditionStatus.TRUE)
392	                    .reason(ConditionReason.STARTED)
393	                    .message("Started successfully")
394	                    .lastTransitionTime(clock.instant())
395	                    .build());
396	            status.setPhase(Plugin.Phase.STARTED);
397	            removeStartTaskIfPresent(pluginName);
398	            requestToReloadPluginsOptionallyDependentOn(pluginName);
399	            return Result.doNotRetry();
400	        }
401	        if (pluginState.isFailed()) {
402	            var t = current.getFailedException();
403	            log.debug("Error occurred when starting plugin {}", pluginName, t);
404	            var writer = new StringWriter();
405	            t.printStackTrace(new PrintWriter(writer));
406	            conditions.addAndEvictFIFO(Condition.builder()
407	                    .type(ConditionType.READY)
408	                    .status(ConditionStatus.FALSE)
409	                    .reason(ConditionReason.START_ERROR)
410	                    .message(writer.toString())
411	                    .lastTransitionTime(clock.instant())
412	                    .build());
413	            status.setPhase(Plugin.Phase.FAILED);
414	            removeStartTaskIfPresent(pluginName);
415	            return Result.doNotRetry();
416	        }
417	        if (!Plugin.Phase.STARTING.equals(status.getPhase())) {
418	            pluginStartTasks.compute(pluginName, (name, old) -> {
419	                if (old != null && !old.isDisposed()) {
420	                    log.info("Cancelling old starting task for plugin {}.", name);
421	                    old.dispose();
422	                    log.info("Cancelled old starting task for plugin {}.", name);
423	                }
424	                return scheduler.schedule(() -> {
425	                    log.info("Starting plugin {} in background thread.", name);
426	                    try {
427	                        var state = pluginManager.startPlugin(name);
428	                        log.info("Plugin {} started with state {}.", name, state);
429	                    } catch (Throwable t) {
430	                        var pluginWrapper = pluginManager.getPlugin(name);
431	                        if (pluginWrapper != null) {
432	                            pluginWrapper.setPluginState(PluginState.FAILED);
433	                            pluginWrapper.setFailedException(t);
434	                        }
435	                    }
436	                });
437	            });
438	            status.setPhase(Plugin.Phase.STARTING);
439	            conditions.addAndEvictFIFO(Condition.builder()
440	                    .type(ConditionType.PROGRESSING)
441	                    .status(ConditionStatus.TRUE)
442	                    .reason(ConditionReason.STARTING)
443	                    .message("Starting plugin " + pluginName)
444	                    .lastTransitionTime(clock.instant())
445	                    .build());
446	        } else {
447	            log.debug("Plugin {} is starting...", pluginName);
448	        }
449	        return Result.requeue(Duration.ofSeconds(2));
450	    }
