452	    private Result checkRequiresVersion(Plugin plugin) {
453	        var pluginName = plugin.getMetadata().getName();
454	        var status = plugin.getStatus();
455	        var conditions = status.getConditions();
456	        var systemVersion = pluginManager.getSystemVersion();
457	        var requires = plugin.getSpec().getRequires();
458	        if (!VersionUtils.satisfiesRequires(systemVersion, requires)) {
459	            removeConditionBy(conditions, ConditionType.PROGRESSING);
460	            conditions.addAndEvictFIFO(Condition.builder()
461	                    .type(ConditionType.READY)
462	                    .status(ConditionStatus.FALSE)
463	                    .reason(ConditionReason.UNSATISFIED_REQUIRES_VERSION)
464	                    .message("Plugin requires Halo version [%s], but the current version is [%s]."
465	                            .formatted(requires, systemVersion))
466	                    .lastTransitionTime(clock.instant())
467	                    .build());
468	            status.setPhase(Plugin.Phase.FAILED);
469	            removeStartTaskIfPresent(pluginName);
470	            return Result.doNotRetry();
471	        }
472	        return null;
473	    }
