475	    void requestToReloadPluginsOptionallyDependentOn(String pluginName) {
476	        var startedPlugins = pluginManager.startedPlugins().stream()
477	                .map(PluginWrapper::getDescriptor)
478	                .toList();
479	        var resolver = new OptionalDependentResolver(startedPlugins);
480	        var dependents = resolver.getOptionalDependents(pluginName);
481	        for (String dependentName : dependents) {
482	            client.fetch(Plugin.class, dependentName).ifPresent(childPlugin -> {
483	                var annotations = MetadataUtil.nullSafeAnnotations(childPlugin);
484	                // loadLocation never be null for started plugins
485	                annotations.put(
486	                        RELOAD_ANNO, childPlugin.getStatus().getLoadLocation().toString());
487	                client.update(childPlugin);
488	            });
489	        }
490	    }
