492	    private Result disablePlugin(Plugin plugin) {
493	        var pluginName = plugin.getMetadata().getName();
494	        var status = plugin.getStatus();
495	        if (pluginManager.getPlugin(pluginName) != null) {
496	            // check if the plugin has children
497	            var dependents = pluginManager.getDependents(pluginName).stream()
498	                    .filter(pw -> PluginState.STARTED.equals(pw.getPluginState()))
499	                    .map(PluginWrapper::getPluginId)
500	                    .toList();
501	            var conditions = status.getConditions();
502	            if (!CollectionUtils.isEmpty(dependents)) {
503	                removeConditionBy(conditions, ConditionType.READY);
504	                conditions.addAndEvictFIFO(Condition.builder()
505	                        .type(ConditionType.PROGRESSING)
506	                        .status(ConditionStatus.UNKNOWN)
507	                        .reason(ConditionReason.WAIT_FOR_DEPENDENTS_DISABLED)
508	                        .message("Wait for children plugins " + dependents + " to be disabled")
509	                        .lastTransitionTime(clock.instant())
510	                        .build());
511	                status.setPhase(Plugin.Phase.DISABLING);
512	                return Result.requeue(Duration.ofSeconds(1));
513	            }
514	            try {
515	                // First, stop starting task if exists
516	                removeStartTaskIfPresent(pluginName);
517	                pluginManager.disablePlugin(pluginName);
518	            } catch (Throwable e) {
519	                log.error("Error occurred when disabling plugin {}", pluginName, e);
520	                conditions.addAndEvictFIFO(Condition.builder()
521	                        .type(ConditionType.READY)
522	                        .status(ConditionStatus.FALSE)
523	                        .reason(ConditionReason.DISABLE_ERROR)
524	                        .message(e.getMessage())
525	                        .lastTransitionTime(clock.instant())
526	                        .build());
527	                status.setPhase(Plugin.Phase.FAILED);
528	                return Result.doNotRetry();
529	            }
530	        }
531	        var conditions = plugin.getStatus().getConditions();
532	        removeConditionBy(conditions, ConditionType.PROGRESSING);
533	        conditions.addAndEvictFIFO(Condition.builder()
534	                .type(ConditionType.READY)
535	                .status(ConditionStatus.TRUE)
536	                .reason(ConditionReason.DISABLED)
537	                .lastTransitionTime(clock.instant())
538	                .build());
539	        plugin.statusNonNull().setPhase(Plugin.Phase.DISABLED);
540	        return null;
541	    }
