548	    private Result resolveStaticResources(Plugin plugin) {
549	        var pluginName = plugin.getMetadata().getName();
550	        var pluginVersion = plugin.getSpec().getVersion();
551	        if (isDevelopmentMode(plugin)) {
552	            // when we are in dev mode, the plugin version is not always changed.
553	            pluginVersion = String.valueOf(clock.instant().toEpochMilli());
554	        }
555	        var status = plugin.statusNonNull();
556	        status.setEntry(null);
557	        status.setStylesheet(null);
558	        var specLogo = plugin.getSpec().getLogo();
559	        if (StringUtils.isNotBlank(specLogo)) {
560	            log.info("Resolving logo resource for plugin {}", pluginName);
561	            // the logo might be:
562	            // 1. URL
563	            // 2. relative path to "resources" folder
564	            // 3. base64 format data image
565	            var logo = specLogo;
566	            if (!specLogo.startsWith("data:image")) {
567	                try {
568	                    logo = new URL(specLogo).toString();
569	                } catch (MalformedURLException ignored) {
570	                    // indicate the logo is a path
571	                    logo = UriComponentsBuilder.newInstance()
572	                            .pathSegment("plugins", pluginName, "assets")
573	                            .path(specLogo)
574	                            .queryParam("version", pluginVersion)
575	                            .build(true)
576	                            .toString();
577	                }
578	            }
579	            status.setLogo(logo);
580	        }
581	
582	        log.info("Resolving main.js and style.css for plugin {}", pluginName);
583	        var resourceLoader = BundleResourceUtils.getResourceLoader(pluginManager, pluginName);
584	        if (resourceLoader == null) {
585	            return null;
586	        }
587	        var bundleLocation = BundleResourceUtils.selectBundleLocation(resourceLoader);
588	        if (bundleLocation == null) {
589	            return null;
590	        }
591	        var entryRes =
592	                BundleResourceUtils.getBundleResource(resourceLoader, bundleLocation, BundleResourceUtils.JS_BUNDLE);
593	        var cssRes =
594	                BundleResourceUtils.getBundleResource(resourceLoader, bundleLocation, BundleResourceUtils.CSS_BUNDLE);
595	        if (entryRes != null && entryRes.exists()) {
596	            var entry = UriComponentsBuilder.newInstance()
597	                    .pathSegment("plugins", pluginName, "assets", bundleLocation, BundleResourceUtils.JS_BUNDLE)
598	                    .queryParam("version", pluginVersion)
599	                    .build(true)
600	                    .toString();
601	            status.setEntry(entry);
602	        }
603	        if (cssRes != null && cssRes.exists()) {
604	            var stylesheet = UriComponentsBuilder.newInstance()
605	                    .pathSegment("plugins", pluginName, "assets", bundleLocation, BundleResourceUtils.CSS_BUNDLE)
606	                    .queryParam("version", pluginVersion)
607	                    .build(true)
608	                    .toString();
609	            status.setStylesheet(stylesheet);
610	        }
611	        return null;
612	    }
