614	    private Result loadOrReload(Plugin plugin) {
615	        var pluginName = plugin.getMetadata().getName();
616	        var p = pluginManager.getPlugin(pluginName);
617	        var conditions = plugin.getStatus().getConditions();
618	
619	        var requestToUnloadBy = requestToUnload(plugin);
620	        var requestToUnload = requestToUnloadBy != null;
621	        var notFullyLoaded = p != null && pluginManager.getUnresolvedPlugins().contains(p);
622	        var alreadyLoaded = p != null && pluginManager.getResolvedPlugins().contains(p);
623	
624	        var requestToReload = requestToReload(plugin);
625	        // TODO Check load location
626	        var shouldUnload = requestToUnload || requestToReload || notFullyLoaded;
627	        if (shouldUnload) {
628	            // check if the plugin is already loaded or not fully loaded.
629	            if (alreadyLoaded || notFullyLoaded) {
630	                // get all dependencies
631	                var dependents = requestToUnloadChildren(pluginName);
632	                if (!CollectionUtils.isEmpty(dependents)) {
633	                    removeConditionBy(conditions, ConditionType.READY);
634	                    conditions.addAndEvictFIFO(Condition.builder()
635	                            .type(ConditionType.PROGRESSING)
636	                            .status(ConditionStatus.UNKNOWN)
637	                            .reason(ConditionReason.WAIT_FOR_DEPENDENTS_UNLOADED)
638	                            .message("Wait for children plugins " + dependents + "to be unloaded")
639	                            .lastTransitionTime(clock.instant())
640	                            .build());
641	                    plugin.getStatus().setPhase(Plugin.Phase.UNKNOWN);
642	                    // wait for children plugins unloaded
643	                    // retry after 1 second
644	                    return Result.requeue(Duration.ofSeconds(1));
645	                }
646	
647	                // unload the plugin exactly
648	                pluginManager.unloadPlugin(pluginName);
649	
650	                removeConditionBy(conditions, ConditionType.INITIALIZED);
651	                removeConditionBy(conditions, ConditionType.PROGRESSING);
652	                removeConditionBy(conditions, ConditionType.READY);
653	
654	                cancelUnloadRequest(pluginName);
655	                p = null;
656	            }
657	
658	            // ensure removing the reload annotation after the plugin is unloaded
659	            if (requestToUnload) {
660	                // skip loading and wait for removing the annotation by other plugins.
661	                var status = plugin.getStatus();
662	                status.getConditions()
663	                        .addAndEvictFIFO(Condition.builder()
664	                                .type(ConditionType.INITIALIZED)
665	                                .status(ConditionStatus.FALSE)
666	                                .reason(ConditionReason.REQUEST_TO_UNLOAD)
667	                                .message("Request to unload by " + requestToUnloadBy)
668	                                .lastTransitionTime(clock.instant())
669	                                .build());
670	                return Result.doNotRetry();
671	            }
672	
673	            if (requestToReload) {
674	                removeRequestToReload(plugin);
675	            }
676	        }
677	
678	        if (requestToEnable(plugin)) {
679	            var result = checkRequiresVersion(plugin);
680	            if (result != null) {
681	                return result;
682	            }
683	        }
684	
685	        // check dependencies before loading
686	        var unresolvedParentPlugins = pluginService.getRequiredDependencies(
687	                plugin, pw -> pw == null || pluginManager.getUnresolvedPlugins().contains(pw));
688	        if (!unresolvedParentPlugins.isEmpty()) {
689	            // requeue if the parent plugin is not loaded yet.
690	            removeConditionBy(conditions, ConditionType.INITIALIZED);
691	            removeConditionBy(conditions, ConditionType.READY);
692	            conditions.addAndEvictFIFO(Condition.builder()
693	                    .type(ConditionType.PROGRESSING)
694	                    .status(ConditionStatus.UNKNOWN)
695	                    .reason(ConditionReason.WAIT_FOR_DEPENDENCIES_LOADED)
696	                    .message("Wait for parent plugins " + unresolvedParentPlugins + " to be loaded")
697	                    .lastTransitionTime(clock.instant())
698	                    .build());
699	            plugin.getStatus().setPhase(Plugin.Phase.UNKNOWN);
700	            return Result.requeue(Duration.ofSeconds(1));
701	        }
702	
703	        if (p == null) {
704	            var loadLocation = plugin.getStatus().getLoadLocation();
705	            log.info("Loading plugin {} from {}", pluginName, loadLocation);
706	            pluginManager.loadPlugin(Paths.get(loadLocation));
707	            plugin.getStatus().setPhase(Plugin.Phase.RESOLVED);
708	            log.info("Loaded plugin {} from {}", pluginName, loadLocation);
709	            conditions.addAndEvictFIFO(Condition.builder()
710	                    .type(ConditionType.INITIALIZED)
711	                    .status(ConditionStatus.TRUE)
712	                    .reason(ConditionReason.LOADED)
713	                    .lastTransitionTime(clock.instant())
714	                    .build());
715	        }
716	
717	        return null;
718	    }
