779	    private Result resolveLoadLocation(Plugin plugin) {
780	        log.debug("Resolving load location for plugin {}", plugin.getMetadata().getName());
781	
782	        // populate load location from annotations
783	        var pluginName = plugin.getMetadata().getName();
784	        var annotations = nullSafeAnnotations(plugin);
785	        var pluginPathAnno = annotations.get(PLUGIN_PATH);
786	        var status = plugin.statusNonNull();
787	        if (isDevelopmentMode(plugin)) {
788	            if (!isInDevEnvironment()) {
789	                status.getConditions()
790	                        .addAndEvictFIFO(Condition.builder()
791	                                .type(ConditionType.INITIALIZED)
792	                                .status(ConditionStatus.FALSE)
793	                                .reason(ConditionReason.INVALID_RUNTIME_MODE)
794	                                .message("""
795	                        Cannot run the plugin with development mode in non-development environment.\
796	                        """)
797	                                .lastTransitionTime(clock.instant())
798	                                .build());
799	                status.setPhase(Plugin.Phase.UNKNOWN);
800	                return Result.doNotRetry();
801	            }
802	            log.debug("Plugin {} is in development mode", pluginName);
803	            if (StringUtils.isBlank(pluginPathAnno)) {
804	                status.getConditions()
805	                        .addAndEvictFIFO(Condition.builder()
806	                                .type(ConditionType.INITIALIZED)
807	                                .status(ConditionStatus.FALSE)
808	                                .reason(ConditionReason.PLUGIN_PATH_NOT_SET)
809	                                .message("""
810	                        Plugin path annotation is not set. \
811	                        Please set plugin path annotation "%s" in development mode.\
812	                        """.formatted(PLUGIN_PATH))
813	                                .build());
814	                return Result.doNotRetry();
815	            }
816	            try {
817	                var loadLocation = ResourceUtils.getURL(pluginPathAnno).toURI();
818	                if (!Objects.equals(status.getLoadLocation(), loadLocation)) {
819	                    log.debug(
820	                            "Populated load location {} for plugin {} from annotation {}",
821	                            loadLocation,
822	                            pluginName,
823	                            pluginPathAnno);
824	                    status.setLoadLocation(loadLocation);
825	                    status.setPhase(Plugin.Phase.RESOLVED);
826	                    status.getConditions()
827	                            .addAndEvictFIFO(Condition.builder()
828	                                    .type(ConditionType.INITIALIZED)
829	                                    .status(ConditionStatus.TRUE)
830	                                    .reason(ConditionReason.LOAD_LOCATION_RESOLVED)
831	                                    .lastTransitionTime(clock.instant())
832	                                    .build());
833	                    log.debug("Populated load location {} for plugin {}", status.getLoadLocation(), pluginName);
834	                }
835	            } catch (URISyntaxException | FileNotFoundException e) {
836	                // TODO Refactor this using event in the future.
837	                var condition = Condition.builder()
838	                        .type(ConditionType.INITIALIZED)
839	                        .status(ConditionStatus.FALSE)
840	                        .reason(ConditionReason.INVALID_PLUGIN_PATH)
841	                        .message("Invalid plugin path " + pluginPathAnno + " configured.")
842	                        .lastTransitionTime(clock.instant())
843	                        .build();
844	                status.getConditions().addAndEvictFIFO(condition);
845	                status.setPhase(Plugin.Phase.UNKNOWN);
846	                return Result.doNotRetry();
847	            }
848	        } else {
849	            // reset annotation PLUGIN_PATH in non-dev mode
850	            var pluginFilename = generateFileName(plugin);
851	            var pluginRoot = pluginManager.getPluginsRoots().stream()
852	                    .filter(root -> Files.exists(root.resolve(pluginFilename)))
853	                    .findFirst()
854	                    .orElse(null);
855	            if (pluginRoot == null) {
856	                var condition = Condition.builder()
857	                        .type(ConditionType.INITIALIZED)
858	                        .status(ConditionStatus.FALSE)
859	                        .reason(ConditionReason.INVALID_PLUGIN_PATH)
860	                        .message("Cannot find plugin file " + pluginFilename + " in plugins roots.")
861	                        .lastTransitionTime(clock.instant())
862	                        .build();
863	                status.getConditions().addAndEvictFIFO(condition);
864	                status.setPhase(Plugin.Phase.UNKNOWN);
865	                return Result.doNotRetry();
866	            }
867	            var pluginPath = pluginRoot.resolve(pluginFilename);
868	            annotations.put(PLUGIN_PATH, pluginRoot.relativize(pluginPath).toString());
869	
870	            // delete old load location if changed.
871	            var oldLoadLocation = status.getLoadLocation();
872	            var newLoadLocation = pluginPath.toUri();
873	            if (oldLoadLocation != null && !Objects.equals(oldLoadLocation, newLoadLocation)) {
874	                // delete the old load location
875	                log.info(
876	                        "Deleting old plugin file {} for plugin {}, and new load location is {}.",
877	                        oldLoadLocation,
878	                        pluginName,
879	                        newLoadLocation);
880	                try {
881	                    var deleted = Files.deleteIfExists(Path.of(oldLoadLocation));
882	                    if (deleted) {
883	                        log.info("Deleted old plugin file {} for plugin {}.", oldLoadLocation, pluginName);
884	                    }
885	                } catch (IOException e) {
886	                    log.warn("Failed to delete old plugin file {} for plugin {}", oldLoadLocation, pluginName, e);
887	                } catch (FileSystemNotFoundException e) {
888	                    log.warn(
889	                            "Failed to delete old plugin file {} for plugin {}: File system not found.",
890	                            oldLoadLocation,
891	                            pluginName,
892	                            e);
893	                }
894	                status.setPhase(Plugin.Phase.RESOLVED);
895	                status.getConditions()
896	                        .addAndEvictFIFO(Condition.builder()
897	                                .type(ConditionType.INITIALIZED)
898	                                .status(ConditionStatus.TRUE)
899	                                .reason(ConditionReason.LOAD_LOCATION_RESOLVED)
900	                                .lastTransitionTime(clock.instant())
901	                                .build());
902	                log.debug("Populated load location {} for plugin {}", status.getLoadLocation(), pluginName);
903	            }
904	            status.setLoadLocation(newLoadLocation);
905	        }
906	        return null;
907	    }
