964	    private List<String> requestToUnloadChildren(String pluginName) {
965	        // get all dependencies
966	        var dependents = pluginManager.getDependents(pluginName).stream()
967	                .map(PluginWrapper::getPluginId)
968	                .toList();
969	        // request all dependents to reload.
970	        dependents.forEach(dependent -> client.fetch(Plugin.class, dependent).ifPresent(childPlugin -> {
971	            var labels = childPlugin.getMetadata().getLabels();
972	            if (labels == null) {
973	                labels = new HashMap<>();
974	                childPlugin.getMetadata().setLabels(labels);
975	            }
976	            var label = labels.get(REQUEST_TO_UNLOAD_LABEL);
977	            if (!pluginName.equals(label)) {
978	                labels.put(REQUEST_TO_UNLOAD_LABEL, pluginName);
979	                client.update(childPlugin);
980	            }
981	        }));
982	        return dependents;
983	    }
984	
985	    private void cancelUnloadRequest(String pluginName) {
986	        // remove label REQUEST_TO_UNLOAD_LABEL
987	        // TODO Use index mechanism
988	        Predicate<Plugin> filter = aplugin -> {
989	            var labels = aplugin.getMetadata().getLabels();
990	            return labels != null && pluginName.equals(labels.get(REQUEST_TO_UNLOAD_LABEL));
991	        };
992	
993	        client.list(Plugin.class, filter, null).forEach(aplugin -> {
994	            var labels = aplugin.getMetadata().getLabels();
995	            if (labels != null && labels.remove(REQUEST_TO_UNLOAD_LABEL) != null) {
996	                client.update(aplugin);
997	            }
998	        });
999	    }
