39	    /**
40	     * Read the file under the classpath as a string.
41	     *
42	     * @param location the file location relative to classpath
43	     * @return file content
44	     */
45	    public static String readClassPathResourceAsString(String location) {
46	        ClassPathResource classPathResource = new ClassPathResource(location);
