61	    public static String userAgentFrom(ServerRequest request) {
62	        HttpHeaders httpHeaders = request.headers().asHttpHeaders();
63	        // https://en.wikipedia.org/wiki/User_agent
64	        String userAgent = httpHeaders.getFirst(HttpHeaders.USER_AGENT);
65	        if (StringUtils.isBlank(userAgent)) {
66	            // https://developer.mozilla.org/en-US/docs/Web/HTTP/Headers/Sec-CH-UA
67	            userAgent = httpHeaders.getFirst("Sec-CH-UA");
