103	     * to encode the string.
104	     *
105	     * @param uri the uri string
106	     * @return the uri
107	     */
108	    public static URI safeToUri(String uri) {
109	        // try to decode first
110	        var decodedUri = UriUtils.decode(uri, StandardCharsets.UTF_8);
111	        UriComponentsBuilder uriBuilder;
