70	                    Set<String> newFinalizers = reverseProxy.getMetadata().getFinalizers();
71	                    if (newFinalizers == null) {
72	                        newFinalizers = new HashSet<>();
73	                        reverseProxy.getMetadata().setFinalizers(newFinalizers);
74	                    }
75	                    newFinalizers.add(FINALIZER_NAME);
76	                    client.update(reverseProxy);
77	                });
78	    }
